import{_ as t,o as e,c as r,a5 as l}from"./chunks/framework.a5no_H3L.js";const p=JSON.parse('{"title":"Controller 与 KRaft","description":"Kafka 集群需要一个\\"管理员\\"来决定谁是 Leader、谁在线、元数据怎么管理。这个管理员就是 Controller。从 ZooKeeper 到 KRaft 的迁移不是\\"换了个存储\\"，而是把这个管理员从\\"外聘\\"变成了\\"内建\\"。","frontmatter":{},"headers":[],"relativePath":"kafka/02-core/chapter-08-controller-and-kraft.md","filePath":"kafka/02-core/chapter-08-controller-and-kraft.md"}'),o={name:"kafka/02-core/chapter-08-controller-and-kraft.md"};function n(d,a,s,c,i,f){return e(),r("div",null,[...a[0]||(a[0]=[l(`<h1 id="controller-与-kraft" tabindex="-1" data-src-line="1" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md">Controller 与 KRaft <a class="header-anchor" href="#controller-与-kraft" aria-label="Permalink to &quot;Controller 与 KRaft&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md"><p data-src-line="3" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md">Kafka 集群需要一个&quot;管理员&quot;来决定谁是 Leader、谁在线、元数据怎么管理。这个管理员就是 Controller。从 ZooKeeper 到 KRaft 的迁移不是&quot;换了个存储&quot;，而是把这个管理员从&quot;外聘&quot;变成了&quot;内建&quot;。</p></blockquote><h2 id="_1-为什么需要-controller" tabindex="-1" data-src-line="5" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md">1. 为什么需要 Controller <a class="header-anchor" href="#_1-为什么需要-controller" aria-label="Permalink to &quot;1. 为什么需要 Controller&quot;">​</a></h2><p data-src-line="7" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md">分布式系统里，有一个基本问题：<strong>谁来决定&quot;谁是什么&quot;？</strong></p><ul data-src-line="9" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md"><li data-src-line="9" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md">哪个 Broker 是 Partition 0 的 Leader？</li><li data-src-line="10" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md">哪些 Broker 在 ISR 中？</li><li data-src-line="11" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md">Broker 3 宕机了，它的分区怎么处理？</li></ul><p data-src-line="13" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md">这些问题不能让 Broker 自己回答——如果两个 Broker 都认为自己是 Leader，就会出现&quot;脑裂&quot;。必须有一个<strong>唯一的权威源</strong>来管理元数据，所有 Broker 向它看齐。</p><p data-src-line="15" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md">这就是 Controller 的角色：集群中唯一有权变更元数据的节点。</p><h2 id="_2-controller-做什么" tabindex="-1" data-src-line="17" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md">2. Controller 做什么 <a class="header-anchor" href="#_2-controller-做什么" aria-label="Permalink to &quot;2. Controller 做什么&quot;">​</a></h2><table tabindex="0"><thead data-src-line="19" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md"><tr data-src-line="19" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md"><th style="text-align:left;">职责</th><th style="text-align:left;">为什么需要它</th></tr></thead><tbody data-src-line="21" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md"><tr data-src-line="21" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md"><td style="text-align:left;">Broker 生死判定</td><td style="text-align:left;">Broker 宕机后需要触发 Leader 选举</td></tr><tr data-src-line="22" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md"><td style="text-align:left;">分区 Leader 选举</td><td style="text-align:left;">Leader 宕机后从 ISR 选新 Leader</td></tr><tr data-src-line="23" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md"><td style="text-align:left;">ISR 变更</td><td style="text-align:left;">Leader 报告 ISR 变化，Controller 确认并广播</td></tr><tr data-src-line="24" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md"><td style="text-align:left;">Topic 生命周期</td><td style="text-align:left;">创建/删除 Topic、分区扩容、副本重分配</td></tr><tr data-src-line="25" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md"><td style="text-align:left;">元数据广播</td><td style="text-align:left;">让所有 Broker 感知上述变更</td></tr></tbody></table><p data-src-line="27" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md">其他 Broker 只是元数据的&quot;观察者&quot;——本地缓存一份，处理 Produce/Fetch 请求。任何要<strong>写</strong>元数据的动作都必须走 Controller。</p><h2 id="_3-zookeeper-模式的问题" tabindex="-1" data-src-line="29" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md">3. ZooKeeper 模式的问题 <a class="header-anchor" href="#_3-zookeeper-模式的问题" aria-label="Permalink to &quot;3. ZooKeeper 模式的问题&quot;">​</a></h2><p data-src-line="31" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md">Kafka 2.8 之前，Controller 依赖外部的 ZooKeeper 集群存储元数据：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>元数据存在 ZooKeeper 的 znode 里：</span></span>
<span class="line"><span>/brokers/ids/&lt;id&gt;                ← Broker 注册</span></span>
<span class="line"><span>/brokers/topics/&lt;topic&gt;/partitions/&lt;n&gt;/state  ← Leader、ISR</span></span>
<span class="line"><span>/controller                      ← 当前 Controller 的临时节点</span></span></code></pre></div><p data-src-line="40" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md">这个架构有四个问题：</p><p data-src-line="42" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md"><strong>单点</strong>：只有一个 Active Controller。它宕机后，新 Controller 需要从 ZooKeeper 重新加载全量元数据——集群越大，恢复越慢。</p><p data-src-line="44" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md"><strong>双写</strong>：元数据的权威存储在 ZooKeeper，Controller 本地还要维护一份运行时状态，两处需要保持一致。这种一致性靠各种边界条件保证，历史上多次出 bug。</p><p data-src-line="46" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md"><strong>扩展瓶颈</strong>：ZooKeeper 模式下 Controller 要 watch 大量 znode，任何变更都要先经 ZK 通知 Controller，再由 Controller 广播给所有 Broker。这条通知链路在分区数和 Broker 数增长时开销显著，Controller 单点成为瓶颈。</p><p data-src-line="48" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md"><strong>运维复杂</strong>：需要单独维护一个 ZooKeeper 集群，它有自己的配置、监控、升级流程。</p><h2 id="_4-kraft-把元数据管理内建到-kafka" tabindex="-1" data-src-line="50" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md">4. KRaft：把元数据管理内建到 Kafka <a class="header-anchor" href="#_4-kraft-把元数据管理内建到-kafka" aria-label="Permalink to &quot;4. KRaft：把元数据管理内建到 Kafka&quot;">​</a></h2><p data-src-line="52" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md">KRaft（Kafka Raft）不是&quot;把 ZooKeeper 换了个地方&quot;，而是用 Raft 共识协议把元数据管理内置到 Kafka 自身。</p><h3 id="架构变化" tabindex="-1" data-src-line="54" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md">架构变化 <a class="header-anchor" href="#架构变化" aria-label="Permalink to &quot;架构变化&quot;">​</a></h3><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ZooKeeper 模式：</span></span>
<span class="line"><span>  Controller ←→ ZooKeeper（外部）←→ Broker</span></span>
<span class="line"><span></span></span>
<span class="line"><span>KRaft 模式：</span></span>
<span class="line"><span>  Controller Quorum（3~5 个节点）—Raft 复制—→ 多数派提交</span></span>
<span class="line"><span>  Broker（observer）—fetch 拉取—→ Active Controller</span></span>
<span class="line"><span>  元数据存储在 Controller 的元数据日志（__cluster_metadata）</span></span></code></pre></div><h3 id="关键区别" tabindex="-1" data-src-line="66" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md">关键区别 <a class="header-anchor" href="#关键区别" aria-label="Permalink to &quot;关键区别&quot;">​</a></h3><table tabindex="0"><thead data-src-line="68" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md"><tr data-src-line="68" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md"><th style="text-align:left;">维度</th><th style="text-align:left;">ZooKeeper</th><th style="text-align:left;">KRaft</th></tr></thead><tbody data-src-line="70" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md"><tr data-src-line="70" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md"><td style="text-align:left;">元数据存储</td><td style="text-align:left;">外部 ZooKeeper</td><td style="text-align:left;">内部 <code>__cluster_metadata</code> 日志</td></tr><tr data-src-line="71" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md"><td style="text-align:left;">Controller 数量</td><td style="text-align:left;">1 个 Active</td><td style="text-align:left;">3 或 5 个（Raft Quorum）</td></tr><tr data-src-line="72" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md"><td style="text-align:left;">故障恢复</td><td style="text-align:left;">重新加载全量元数据</td><td style="text-align:left;">Raft 自动选主，增量追赶</td></tr><tr data-src-line="73" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md"><td style="text-align:left;">元数据传播</td><td style="text-align:left;">ZK watch + 本地缓存</td><td style="text-align:left;">Broker 主动拉取（fetch）</td></tr><tr data-src-line="74" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md"><td style="text-align:left;">外部依赖</td><td style="text-align:left;">需要 ZooKeeper 集群</td><td style="text-align:left;">不需要 ZooKeeper 集群</td></tr></tbody></table><h3 id="为什么-raft-比-zookeeper-更好" tabindex="-1" data-src-line="76" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md">为什么 Raft 比 ZooKeeper 更好 <a class="header-anchor" href="#为什么-raft-比-zookeeper-更好" aria-label="Permalink to &quot;为什么 Raft 比 ZooKeeper 更好&quot;">​</a></h3><p data-src-line="78" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md">Raft 是一种共识协议，它的核心思想是：<strong>多数节点同意才能提交</strong>。KRaft Controller Quorum 中有 3~5 个节点，Active Controller（Raft Leader）接收元数据写入，复制到多数节点后才提交。</p><p data-src-line="80" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md">Active Controller 故障时，Raft 自动选举新 Leader。Raft 的选举规则保证新 Leader 一定拥有全部已提交的元数据。投票者只会把选票投给日志不比自己旧的候选者（比较最后任期和偏移量），而任何已提交日志都已复制到多数派节点——候选者要凑齐多数派选票，就必须覆盖这些已提交日志，否则持有它们的节点不会投票给它。未提交的日志则可能在换届时被覆盖。因此新 Leader 无需像 ZooKeeper 模式那样从外部存储全量重载元数据。这是架构上的优势：恢复不再随集群规模线性恶化，但实际恢复时间仍取决于选举耗时、日志追赶和状态重建。</p><h3 id="元数据传播" tabindex="-1" data-src-line="82" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md">元数据传播 <a class="header-anchor" href="#元数据传播" aria-label="Permalink to &quot;元数据传播&quot;">​</a></h3><p data-src-line="84" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md">元数据传播分两条路径。Controller 之间：Active Controller 把元数据变更写入 <code>__cluster_metadata</code> 这个单分区元数据日志，通过 Raft 复制到其他 Controller，多数派确认后才提交。Controller 与 Broker 之间：Broker 是元数据日志的 observer（观察者），不参与投票，而是通过 fetch 机制定期向 Active Controller 拉取元数据增量并更新本地缓存——这与普通消费者组消费业务 Topic 是两回事。</p><p data-src-line="86" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md">这套&quot;拉&quot;模式比 ZooKeeper 的 watch&quot;推&quot;模式更高效。watch 模式下每个 znode 变更都要通知所有 watch 者，Controller 的推送压力随 Broker 数和分区数增长；fetch 模式下 Broker 按自己的节奏拉取，落后时只补增量，Controller 不承担主动推送的负担。</p><h2 id="_5-迁移的影响" tabindex="-1" data-src-line="88" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md">5. 迁移的影响 <a class="header-anchor" href="#_5-迁移的影响" aria-label="Permalink to &quot;5. 迁移的影响&quot;">​</a></h2><table tabindex="0"><thead data-src-line="90" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md"><tr data-src-line="90" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md"><th style="text-align:left;">维度</th><th style="text-align:left;">影响</th></tr></thead><tbody data-src-line="92" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md"><tr data-src-line="92" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md"><td style="text-align:left;">运维</td><td style="text-align:left;">不再需要维护 ZooKeeper 集群</td></tr><tr data-src-line="93" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md"><td style="text-align:left;">可用性</td><td style="text-align:left;">多 Controller 内置冗余，故障恢复更快</td></tr><tr data-src-line="94" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md"><td style="text-align:left;">扩展性</td><td style="text-align:left;">元数据管理不再受 ZK 限制，支持更大规模的集群</td></tr><tr data-src-line="95" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md"><td style="text-align:left;">兼容性</td><td style="text-align:left;">Kafka 4.0 移除 ZK 支持，升级需要先迁移到 KRaft</td></tr></tbody></table><h2 id="_6-配置" tabindex="-1" data-src-line="97" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md">6. 配置 <a class="header-anchor" href="#_6-配置" aria-label="Permalink to &quot;6. 配置&quot;">​</a></h2><p data-src-line="99" data-src-file="kafka/02-core/chapter-08-controller-and-kraft.md">下面的示例是<strong>静态 Quorum</strong> 配置，<code>controller.quorum.voters</code> 显式列出所有投票节点。Kafka 3.9 起支持<strong>动态 Quorum</strong>（KIP-853），改用 <code>controller.quorum.bootstrap.servers</code> 引导发现 Quorum，运行时可通过 <code>kafka-metadata-quorum.sh</code> 增删 Controller。静态或动态 Quorum 在集群格式化时决定；Kafka 4.1 起可按迁移流程把已运行的静态 Quorum 转为动态，不能仅靠修改配置项切换。新集群部署优先考虑动态 Quorum。</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># KRaft 模式（静态 Quorum）</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">process.roles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=broker,controller    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 合并部署；生产环境建议分离为 broker 与 controller 独立节点</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">node.id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">controller.quorum.voters</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=1@host1:9093,2@host2:9093,3@host3:9093   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 动态 Quorum 改用 controller.quorum.bootstrap.servers</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">controller.listener.names</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=CONTROLLER</span></span></code></pre></div>`,35)])])}const h=t(o,[["render",n]]);export{p as __pageData,h as default};
